const {createRequire}=require('node:module');
const require=createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const {chromium}=require('playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,args:['--no-sandbox']});
 const errors=[];
 for(const width of [320,390,1280]){
  const page=await browser.newPage({viewport:{width,height:900}});
  page.on('pageerror',e=>errors.push(e.message));
  await page.goto('http://127.0.0.1:4173');
  await page.waitForSelector('.fret');
  const before=await page.evaluate(()=>({viewport:innerWidth,doc:document.documentElement.scrollWidth,board:document.querySelector('.fretboard').getBoundingClientRect().width,wrap:document.querySelector('.board-wrap').getBoundingClientRect().width}));
  await page.locator('#showAllNotes').check();
  const revealed=await page.locator('.fret').evaluateAll(nodes=>nodes.every(n=>getComputedStyle(n).color!=='rgba(0, 0, 0, 0)'&&getComputedStyle(n).color!=='transparent'));
  if(width===320){
   await page.evaluate(()=>{window.heard=[];const original=AudioContext.prototype.createOscillator;AudioContext.prototype.createOscillator=function(){const o=original.call(this);Object.defineProperty(o.frequency,'value',{set(v){window.heard.push(v)},get(){return 0}});return o}});
   await page.locator('.fret[data-midi="40"]').click();
   const hz=await page.evaluate(()=>window.heard[0]);
   console.log(JSON.stringify({width,before,revealed,lowEHz:hz,expectedLowE:440*Math.pow(2,(40-69)/12)}));
  } else console.log(JSON.stringify({width,before,revealed}));
  await page.close();
 }
 console.log('page errors:',JSON.stringify(errors));
 await browser.close();
 if(errors.length)process.exitCode=1;
})().catch(e=>{console.error(e);process.exitCode=1});
