node <<'JS'
const {createRequire}=require('node:module');
const runtimeRequire=createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const {chromium}=runtimeRequire('playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,args:['--no-sandbox']});
 const errors=[];
 for(const width of [320,390,1280]){
  const page=await browser.newPage({viewport:{width,height:900}});
  page.on('pageerror',e=>errors.push(`${width}px: ${e.message}`));
  await page.goto('http://127.0.0.1:4173');
  await page.waitForSelector('.fret');
  const dimensions=await page.evaluate(()=>({viewport:innerWidth,document:document.documentElement.scrollWidth,board:Math.round(document.querySelector('.fretboard').getBoundingClientRect().width),wrap:Math.round(document.querySelector('.board-wrap').getBoundingClientRect().width)}));
  await page.locator('#showAllNotes').check({timeout:5000});
  const enabled=await page.locator('.fretboard').evaluate(el=>el.classList.contains('show-all'));
  if(!enabled) throw new Error(`Show-all toggle did not activate at ${width}px`);
